    end

    local function named_court_parts(s)
        local surfaces,lines={},{}
        local roots={}; for _,name in ipairs({"Map","Courts","Court"}) do local object=workspace:FindFirstChild(name); if object then roots[#roots+1]=object end end
        local seen={}
